        ['key' => 'laravel-mcp', 'name' => 'Laravel MCP', 'repo' => 'https://github.com/laravel/mcp', 'identifier_scheme' => 'git_commit', 'identifier' => '3d365d5db3493c806d190f3404cd7431634ca4e1', 'source_version' => '3d365d5db3493c806d190f3404cd7431634ca4e1', 'source_updated_at' => '2026-07-16', 'release_version' => '0.8.2', 'license' => 'MIT', 'legal_basis' => 'mit_reference_independent_implementation', 'priority' => 'P1', 'area' => 'laravel_ai', 'status' => 'structured_content_serialization_test_delta_reviewed_no_runtime_gap', 'last_reviewed_at' => '2026-07-16', 'next_action' => 'Revision 3d365d5db3493c806d190f3404cd7431634ca4e1 serializes enum and numeric values through JSON before Laravel MCP test assertions. PLOS external MCP results already cross JSON-RPC and are validated after JSON decoding against advertised outputSchema, so no runtime mismatch was reproduced. Retain bounded dynamic tools, cancellation, real stdio tests, and native result validation without adding the Laravel MCP dependency.'],
        ['key' => 'laravel-boost', 'name' => 'Laravel Boost', 'repo' => 'https://github.com/laravel/boost', 'identifier_scheme' => 'git_commit', 'identifier' => '70d0245f3b624f7565d9dcf61dead8da35e28a50', 'source_version' => '70d0245f3b624f7565d9dcf61dead8da35e28a50', 'source_updated_at' => '2026-07-15', 'license' => 'MIT', 'legal_basis' => 'mit_security_delta_reference_no_runtime_adoption', 'priority' => 'reference', 'area' => 'laravel_ai', 'status' => 'rejected_watch_only_security_delta_reviewed', 'monitor_cadence_days' => 90, 'last_reviewed_at' => '2026-07-16', 'next_action' => 'Keep rejected unless the operator explicitly reopens it. Revision 70d0245f3b624f7565d9dcf61dead8da35e28a50 prevents script injection into partial HTML by requiring an actual html or head tag instead of matching header. PLOS has no Boost response injector or matching gap; import no package, middleware, browser logger, or script.'],
        ['key' => 'prism-php', 'name' => 'Prism PHP', 'repo' => 'https://github.com/prism-php/prism', 'license' => 'MIT', 'priority' => 'P2', 'area' => 'laravel_ai', 'status' => 'reviewed_no_runtime_fit', 'last_reviewed_at' => '2026-07-13', 'next_action' => 'Keep as a PHP provider/tool comparison point. Revisit its tool-artifact envelope only when a PLOS agent tool must return binary or rich output separately from lossless model-visible text; do not duplicate the table-owned PLOS provider control plane.'],
        ['key' => 'playwright-mcp', 'name' => 'Playwright MCP', 'repo' => 'https://github.com/microsoft/playwright-mcp', 'identifier_scheme' => 'git_commit', 'identifier' => '55679f5f3d4b4f3e2534ec0ce2fc5683ba2eaf3f', 'source_version' => '55679f5f3d4b4f3e2534ec0ce2fc5683ba2eaf3f', 'source_updated_at' => '2026-07-15', 'license' => 'Apache-2.0', 'priority' => 'P0', 'area' => 'browser_mcp', 'status' => 'browser_mcp_watch', 'last_reviewed_at' => '2026-07-15', 'next_action' => 'Keep PLOS browser contexts isolated, authenticated, host/origin checked, allowlisted, and content-bounded. Revision 55679f5f3d4b4f3e2534ec0ce2fc5683ba2eaf3f changes a devcontainer version, README typo, and declaration shebang only; it exposes no PLOS browser security or UI-contract gap.'],
        ['key' => 'mcp-inspector', 'name' => 'MCP Inspector', 'repo' => 'https://github.com/modelcontextprotocol/inspector', 'identifier_scheme' => 'git_commit', 'identifier' => 'ac3c1a122a5e072a200c99869fc0cd8bfa660ece', 'source_version' => 'ac3c1a122a5e072a200c99869fc0cd8bfa660ece', 'source_updated_at' => '2026-07-18', 'release_version' => '1.0.0', 'license' => 'Apache-2.0/MIT transition; documentation CC-BY-4.0', 'legal_basis' => 'official_protocol_and_cli_behavior_reference_no_source_copied', 'priority' => 'P0', 'area' => 'browser_mcp', 'status' => 'content_free_mcp_probe_failure_receipt_integrated', 'last_reviewed_at' => '2026-07-19', 'next_action' => 'Revision ac3c1a122a5e072a200c99869fc0cd8bfa660ece adds dependency security fixes and blocks link-local/cloud-metadata SSRF across redirects, including IPv4-mapped IPv6. PLOS already requires every browser navigation and redirect hostname to resolve exclusively to public-unicast addresses, a stricter applicable boundary. Keep bearer authentication, Host/Origin checks, and one content-free no-retry MCP failure receipt; install no Inspector runtime or dependency.'],
        ['key' => 'microsoft-mcp-gateway', 'name' => 'Microsoft MCP Gateway', 'repo' => 'https://github.com/microsoft/mcp-gateway', 'identifier_scheme' => 'git_commit', 'identifier' => '6f1b11afa3a8c852393e37c1105a1d56f89e2b59', 'source_version' => '6f1b11afa3a8c852393e37c1105a1d56f89e2b59', 'source_updated_at' => '2026-06-26', 'license' => 'MIT', 'legal_basis' => 'mit_authorization_pattern_independent_native_php_implementation', 'priority' => 'P0', 'area' => 'browser_mcp', 'status' => 'agent_declared_tool_contract_integrated', 'fit' => 'agent and MCP tool authorization, definition validation, and runtime least privilege', 'sidecar_policy' => 'reference_only_no_gateway_runtime', 'plos_surface' => 'phase-derived agent tool allowlists, fail-closed permissions, and pre-session declaration resolution', 'monitor_cadence_days' => 14, 'last_reviewed_at' => '2026-07-15', 'next_action' => 'Keep phase-only agents limited to the ordered union of their declared phase tools, require every registered tool permission even when the agent declares none, and block unresolved declarations before session, cache, tool, or model access. Retain invocation-time contract enforcement plus existing operator confirmation and offline policy gates. No gateway runtime, Kubernetes control plane, Azure identity, prompt, model, or source was added.'],
        ['key' => 'mcp-typescript-sdk', 'name' => 'MCP TypeScript SDK', 'repo' => 'https://github.com/modelcontextprotocol/typescript-sdk', 'identifier_scheme' => 'git_commit', 'identifier' => 'f60dff0674954ab516739f21ad9905349c8e9249', 'source_version' => 'f60dff0674954ab516739f21ad9905349c8e9249', 'source_updated_at' => '2026-07-17', 'release_version' => '1.30.1', 'adopted_source_version' => '289ac2c3af7e1536160e80414296b175171a1a87', 'license' => 'Adopted v1 package MIT; monitored v2 Apache-2.0/MIT transition', 'legal_basis' => 'mit_direct_npm_dependency', 'priority' => 'P0', 'area' => 'browser_mcp', 'status' => 'sdk_stdio_contract_probe_integrated', 'fit' => 'trusted local MCP client/server lifecycle and contract integrity', 'sidecar_policy' => 'direct_locked_runtime_dependency', 'plos_surface' => 'mcp-servers/plos stdio server and content-free tool-contract audit', 'monitor_cadence_days' => 14, 'breakthrough_signals' => ['v1 security or transport fix', 'stable v2 release', 'protocol lifecycle change', 'pagination or shutdown fix'], 'last_reviewed_at' => '2026-09-27', 'next_action' => 'The adopted v1.30.1 npm artifact maps to revision 289ac2c3af7e1536160e80414296b175171a1a87. September 27 security maintenance retains the v1 protocol and exact external-runtime admission. All 31 live tool contracts match the existing baseline and 94 PLOS MCP tests pass. The older monitored v2 source revision is historical; qualify a future major migration separately.'],
        ['key' => 'mcp-servers', 'name' => 'Model Context Protocol Servers', 'repo' => 'https://github.com/modelcontextprotocol/servers', 'identifier_scheme' => 'git_commit', 'identifier' => 'd31124c982401739917fd817c2a59db344529c16', 'source_version' => 'd31124c982401739917fd817c2a59db344529c16', 'source_updated_at' => '2026-07-06', 'release_version' => '@modelcontextprotocol/server-everything@2026.7.4', 'integrity' => 'sha512-ydMW/M6rk9tK23b+U38trsNLHhd5eF+ntiv2Vr+RPMDhbiKY/IKrZU25ukvSXVPUBvy7TxTPWpeV4KcYcXg72w==', 'license' => 'Apache-2.0/MIT transition; documentation CC-BY-4.0; bundled package license controls', 'legal_basis' => 'licensed_direct_exact_npm_runtime_dependency', 'priority' => 'P0', 'area' => 'browser_mcp', 'status' => 'exact_external_mcp_runtime_pin_admission_integrated_disabled_by_default', 'fit' => 'deterministic local MCP conformance fixture without invocation-time package resolution', 'sidecar_policy' => 'direct_locked_runtime_dependency_disabled_by_default', 'plos_surface' => 'operator-enabled Everything fixture plus fail-closed admission for every enabled external MCP runtime', 'monitor_cadence_days' => 14, 'last_reviewed_at' => '2026-07-15', 'next_action' => 'Keep Everything disabled by default because its current catalog can inspect environment values, mutate session state, and fetch open-world URLs. When deliberately enabled, require exact manifest and lock versions with lock integrity, installed-version, and binary-ownership evidence. Deny npx, uvx, shells, Python module launchers, mutable container launchers, unresolved interpreters, and denied-runtime static catalogs before invocation; retain direct operator or repository binaries under content identity.'],
        ['key' => 'model-context-protocol-spec', 'name' => 'Model Context Protocol Specification', 'repo' => 'https://github.com/modelcontextprotocol/modelcontextprotocol', 'identifier_scheme' => 'spec_version', 'identifier' => '2025-11-25', 'source_version' => '2025-11-25', 'source_updated_at' => '2025-11-25', 'license' => 'Specifications and new code Apache-2.0; legacy contributions may remain MIT; non-specification documentation CC-BY-4.0', 'priority' => 'P0', 'area' => 'browser_mcp', 'status' => 'external_result_schema_validation_integrated', 'last_reviewed_at' => '2026-07-15', 'next_action' => 'Keep server-side schema-bearing PLOS tools and client-side external MCP results fail-closed on missing or nonconforming successful structured output. Preserve tool execution errors for correction, retain content-free validation logs, and do not trust annotations or widen tool authority.'],
        ['key' => 'browser-use', 'name' => 'Browser Use', 'repo' => 'https://github.com/browser-use/browser-use', 'identifier_scheme' => 'git_commit', 'identifier' => 'dbc4d46e0ca59afbba020d456aa10d930279330c', 'source_version' => 'dbc4d46e0ca59afbba020d456aa10d930279330c', 'source_updated_at' => '2026-07-14', 'license' => 'MIT', 'legal_basis' => 'mit_reference_independent_implementation', 'priority' => 'P0', 'area' => 'browser_mcp', 'status' => 'browser_ip_target_gate_integrated', 'last_reviewed_at' => '2026-07-16', 'next_action' => 'Keep browser-canonical IP literals and localhost blocked before trusted-initial or allowlist handling, alongside operation-scoped navigation, popup blocking, and lossless content windows. Do not claim DNS-resolved private-address or rebinding protection, and do not add Browser Use cloud, profiles, credentials, or autonomous action authority.'],
