        ['key' => 'fastmcp', 'name' => 'FastMCP', 'repo' => 'https://github.com/PrefectHQ/fastmcp', 'identifier_scheme' => 'git_commit', 'identifier' => '67e8448389c5149bb7f71a54323bbd00e3c32b86', 'source_version' => '67e8448389c5149bb7f71a54323bbd00e3c32b86', 'source_updated_at' => '2026-07-19', 'license' => 'Apache-2.0', 'legal_basis' => 'apache_2_0_progress_contract_reference_native_typescript_implementation', 'priority' => 'P0', 'area' => 'browser_mcp', 'status' => 'mcp_progress_heartbeat_integrated', 'last_reviewed_at' => '2026-07-19', 'next_action' => 'Revision 67e8448389c5149bb7f71a54323bbd00e3c32b86 adds path-safe templated resources, non-mutating schema compression, disconnected-task cleanup, telemetry controls, caching, and an MCP v2 beta migration. PLOS exposes tools rather than templated MCP resources or durable MCP tasks, canonicalizes contracts without mutation, and keeps telemetry content-free; retain the existing progress and cancellation contract without adding the Python runtime, proxy, cache, or beta protocol route.'],
