        ['key' => 'semgrep', 'name' => 'Semgrep', 'repo' => 'https://github.com/semgrep/semgrep', 'identifier_scheme' => 'git_commit', 'identifier' => '1f15ff4eb9f56f5a3b6a9afb958bdc82b5b6bcb0', 'source_version' => '1f15ff4eb9f56f5a3b6a9afb958bdc82b5b6bcb0', 'source_updated_at' => '2026-07-16', 'release_version' => '1.170.0', 'license' => 'LGPL-2.1 code; official rule and finding-triage documentation referenced separately', 'legal_basis' => 'public_behavior_fact_reference_independent_native_php_implementation', 'priority' => 'P1', 'area' => 'framework_ops', 'status' => 'source_scan_completeness_reporting_integrated', 'last_reviewed_at' => '2026-07-16', 'next_action' => 'Keep runtime-policy matches visible and definition contexts table-owned. Semgrep 1.170.0 reports time-limit exhaustion regardless of partial findings; PLOS independently applies that completeness invariant to whiteroom:source-drift through explicit coverage counts, bounded reason codes, partial-result preservation, and opt-in --require-complete failure. Add no Semgrep engine, managed service, source, rules, telemetry, or account dependency.'],
