        ['key' => 'qwen-agent', 'name' => 'Qwen-Agent', 'repo' => 'https://github.com/QwenLM/Qwen-Agent', 'identifier_scheme' => 'git_commit', 'identifier' => '31a4d36d123688581a9e9744427272b33ce940e0', 'source_version' => '31a4d36d123688581a9e9744427272b33ce940e0', 'source_updated_at' => '2026-03-04', 'license' => 'Apache-2.0', 'legal_basis' => 'apache_2_0_native_tool_parser_reference_no_runtime_import', 'priority' => 'P0', 'area' => 'developer_agent', 'status' => 'model_tool_capability_and_cli_trajectory_integrated', 'last_reviewed_at' => '2026-07-15', 'next_action' => 'Keep coding quality separate from exact native tool-protocol admission. Qwen3-Coder upstream recommends its native parsed tool-call route; do not translate ambiguous malformed patch payloads or add the Python agent runtime. Retain evaluator-owned verification and content-free completed-command telemetry while monitoring Qwen/Ollama parser changes.'],
